# -----------------------------------------------------------------------------
# Data pipeline helpers: jcomplete / jsubset storage and application
# These helpers manage per-dataset filter and complete-case settings,
# apply them in the correct order, and generate info-line messages.
# -----------------------------------------------------------------------------

#' Internal helper: get filter settings for a named data frame
#'
#' Looks up the \code{jsubset()} settings stored under the
#' \code{.jst_filter} option for a specific data frame name. Returns
#' \code{NULL} if no filter is set for that data frame.
#'
#' @param data_name Character string giving the data frame name to look
#'   up. If \code{NULL}, returns \code{NULL}.
#'
#' @return The stored filter settings list, or \code{NULL} if none.
#'
#' @keywords internal
.jst_get_filter <- function(data_name) {
  if (is.null(data_name) || length(data_name) != 1L ||
      is.na(data_name) || !nzchar(data_name)) return(NULL)
  all_filters <- getOption(".jst_filter", default = list())
  all_filters[[data_name]]
}

#' Internal helper: get complete-case settings for a named data frame
#'
#' Looks up the \code{jcomplete()} settings stored under the
#' \code{.jst_complete} option for a specific data frame name. Returns
#' \code{NULL} if no complete-case settings are stored for that data
#' frame.
#'
#' @param data_name Character string giving the data frame name to look
#'   up. If \code{NULL}, returns \code{NULL}.
#'
#' @return The stored complete-case settings list, or \code{NULL} if
#'   none.
#'
#' @keywords internal
.jst_get_complete <- function(data_name) {
  if (is.null(data_name) || length(data_name) != 1L ||
      is.na(data_name) || !nzchar(data_name)) return(NULL)
  all_complete <- getOption(".jst_complete", default = list())
  all_complete[[data_name]]
}

#' Internal helper: set filter settings for a named data frame
#'
#' Stores filter settings under the \code{.jst_filter} option, keyed by
#' data frame name. Used internally by \code{jsubset()}.
#'
#' @param data_name Character string giving the data frame name. If
#'   \code{NULL}, the call is a silent no-op.
#' @param settings A list of filter settings to store.
#'
#' @return \code{invisible(NULL)}. Called for its side effect on the
#'   \code{.jst_filter} option.
#'
#' @keywords internal
.jst_set_filter <- function(data_name, settings) {
  if (is.null(data_name) || length(data_name) != 1L ||
      is.na(data_name) || !nzchar(data_name)) return(invisible(NULL))
  all_filters <- getOption(".jst_filter", default = list())
  all_filters[[data_name]] <- settings
  options(.jst_filter = all_filters)
}

#' Internal helper: set complete-case settings for a named data frame
#'
#' Stores complete-case settings under the \code{.jst_complete} option,
#' keyed by data frame name. Used internally by \code{jcomplete()}.
#'
#' @param data_name Character string giving the data frame name. If
#'   \code{NULL}, the call is a silent no-op.
#' @param settings A list of complete-case settings to store.
#'
#' @return \code{invisible(NULL)}. Called for its side effect on the
#'   \code{.jst_complete} option.
#'
#' @keywords internal
.jst_set_complete <- function(data_name, settings) {
  if (is.null(data_name) || length(data_name) != 1L ||
      is.na(data_name) || !nzchar(data_name)) return(invisible(NULL))
  all_complete <- getOption(".jst_complete", default = list())
  all_complete[[data_name]] <- settings
  options(.jst_complete = all_complete)
}

#' Internal helper: report whether any data frame has an active filter
#'
#' Scans the \code{.jst_filter} option to see whether any data frame
#' has filter settings currently turned on. Used to drive informational
#' notes about filtering being active for some other dataset than the
#' one currently in use.
#'
#' @return Logical. \code{TRUE} if at least one data frame has an active
#'   filter setting; \code{FALSE} otherwise.
#'
#' @keywords internal
.jst_any_filter_active <- function() {
  all_filters <- getOption(".jst_filter", default = list())
  if (length(all_filters) == 0) return(FALSE)
  for (nm in names(all_filters)) {
    fs <- all_filters[[nm]]
    if (!is.null(fs) && isTRUE(fs$active)) return(TRUE)
  }
  FALSE
}

#' Internal helper: report whether any data frame has active complete-case settings
#'
#' Scans the \code{.jst_complete} option to see whether any data frame
#' has complete-case settings currently turned on. Used to drive
#' informational notes about complete-case handling being active for
#' some other dataset than the one currently in use.
#'
#' @return Logical. \code{TRUE} if at least one data frame has active
#'   complete-case settings; \code{FALSE} otherwise.
#'
#' @keywords internal
.jst_any_complete_active <- function() {
  all_complete <- getOption(".jst_complete", default = list())
  if (length(all_complete) == 0) return(FALSE)
  for (nm in names(all_complete)) {
    cs <- all_complete[[nm]]
    if (!is.null(cs) && isTRUE(cs$active)) return(TRUE)
  }
  FALSE
}

#' Internal helper: get registered dummy variables for a named data frame
#'
#' Looks up the \code{jdummy()} registrations stored under the
#' \code{.jst_dummy} option for a specific data frame name. Returns
#' \code{NULL} if no dummies are registered for that data frame.
#'
#' @param data_name Character string giving the data frame name to look
#'   up.
#'
#' @return The stored dummy-registration settings list, or \code{NULL}
#'   if none.
#'
#' @keywords internal
.jst_get_dummy <- function(data_name) {
  if (is.null(data_name) || length(data_name) != 1L ||
      is.na(data_name) || !nzchar(data_name)) return(NULL)
  all_dummy <- getOption(".jst_dummy", default = list())
  all_dummy[[data_name]]
}

#' Internal helper: set registered dummy variables for a named data frame
#'
#' Stores dummy registrations under the \code{.jst_dummy} option, keyed
#' by data frame name. Used internally by \code{jdummy()}.
#'
#' @param data_name Character string giving the data frame name.
#' @param settings A list of dummy registrations to store.
#'
#' @return \code{invisible(NULL)}. Called for its side effect on the
#'   \code{.jst_dummy} option.
#'
#' @keywords internal
.jst_set_dummy <- function(data_name, settings) {
  if (is.null(data_name) || length(data_name) != 1L ||
      is.na(data_name) || !nzchar(data_name)) return(invisible(NULL))
  all_dummy <- getOption(".jst_dummy", default = list())
  all_dummy[[data_name]] <- settings
  options(.jst_dummy = all_dummy)
}

#' Internal helper: get the intent registry for a named data frame
#'
#' Looks up the analysis-role intent records stored under the
#' \code{.jst_registry} option for a specific data frame name. This is the
#' general intent notebook for jnumeric()/jcount() registrations; it follows
#' the same session-option, frame-keyed model as \code{.jst_dummy} but is a
#' separate store, so the existing dummy consumers are unaffected. Records are
#' a named list keyed by variable name (lookup and replace are the dominant
#' operations), each a list with at least \code{kind} (one of "numeric" or
#' "count"; the slot is general enough for later facets such as centering).
#'
#' @param data_name Character string giving the data frame name to look up.
#' @return The stored intent records (a named list), or \code{NULL} if none.
#' @keywords internal
.jst_get_registry <- function(data_name) {
  if (is.null(data_name) || length(data_name) != 1L ||
      is.na(data_name) || !nzchar(data_name)) return(NULL)
  all_reg <- getOption(".jst_registry", default = list())
  all_reg[[data_name]]
}

#' Internal helper: set the intent registry for a named data frame
#'
#' Stores analysis-role intent records under the \code{.jst_registry} option,
#' keyed by data frame name. Used internally by the registration functions
#' (jnumeric, jcount).
#'
#' @param data_name Character string giving the data frame name.
#' @param settings A named list of intent records (keyed by variable name),
#'   or \code{NULL} to clear the registry for this frame.
#' @return \code{invisible(NULL)}. Called for its side effect on the
#'   \code{.jst_registry} option.
#' @keywords internal
.jst_set_registry <- function(data_name, settings) {
  if (is.null(data_name) || length(data_name) != 1L ||
      is.na(data_name) || !nzchar(data_name)) return(invisible(NULL))
  all_reg <- getOption(".jst_registry", default = list())
  all_reg[[data_name]] <- settings
  options(.jst_registry = all_reg)
}

#' Internal helper: look up a single variable's registered intent
#'
#' Returns the intent record for one variable in a named data frame, or
#' \code{NULL} if the variable has no registered intent. Consulted by the
#' classification resolver (tier 2) and by the registration functions.
#'
#' @param data_name Character string giving the data frame name.
#' @param var_name Character string giving the variable name.
#' @return The intent record (a list with at least \code{kind}), or
#'   \code{NULL}.
#' @keywords internal
.jst_get_intent <- function(data_name, var_name) {
  reg <- .jst_get_registry(data_name)
  if (is.null(reg)) return(NULL)
  reg[[var_name]]
}

#' Internal helper: bake classification registrations onto a frame for saving
#'
#' Gathers the active classification registrations for a named data frame --
#' the jnumeric/jcount intent records (the .jst_registry notebook) and the
#' jdummy registrations (the .jst_dummy registry) -- and attaches them to the
#' data frame as a single list-valued attribute (".jst_registrations") so they
#' travel inside an R format (.rds) save. The original frame name is
#' recorded alongside as provenance only; it is informational and is NOT used
#' as the lookup key on load (jload re-keys under the name the frame is loaded
#' as, which is the name later analysis calls will reference). The attribute is
#' attached only when at least one registration exists, so a frame with none is
#' returned unchanged and saves without the attribute. Courier prune (S208):
#' only registrations whose variables are present in the frame being saved are
#' baked -- the file's card describes the file's contents. Stale entries are
#' left out of the attribute (and reported back to jsave for a note) while the
#' session notebook itself is left untouched; a card emptied entirely by the
#' prune is not attached at all, so a later jload takes the carries-none path.
#' Only the .rds format
#' carries arbitrary R attributes, so this is called only on the .rds save path.
#'
#' @param data A data frame.
#' @param data_name Character string giving the data frame name to look up in
#'   the two registries.
#' @return A list with two elements: \code{data} (the data frame, with a
#'   ".jst_registrations" attribute attached when at least one surviving
#'   registration exists) and \code{dropped} (character vector of variable
#'   names whose registrations were pruned; empty when none were).
#' @keywords internal
.jst_bake_registrations <- function(data, data_name) {
  reg   <- .jst_get_registry(data_name)
  dummy <- .jst_get_dummy(data_name)
  if (is.null(reg) && is.null(dummy)) {
    return(list(data = data, dropped = character(0)))
  }

  # Courier prune (S208): bake only registrations whose variables are in the
  # frame being saved. The session notebook is NOT touched, so the save-side
  # note is recoverable in-session (rebuild the variable and save again).
  cols    <- names(data)
  dropped <- character(0)
  if (!is.null(reg)) {
    stale <- setdiff(names(reg), cols)
    if (length(stale) > 0) {
      dropped <- c(dropped, stale)
      reg <- reg[setdiff(names(reg), stale)]
      if (length(reg) == 0) reg <- NULL
    }
  }
  if (!is.null(dummy)) {
    stale <- setdiff(names(dummy), cols)
    if (length(stale) > 0) {
      dropped <- c(dropped, stale)
      dummy <- dummy[setdiff(names(dummy), stale)]
      if (length(dummy) == 0) dummy <- NULL
    }
  }
  dropped <- unique(dropped)

  if (is.null(reg) && is.null(dummy)) {
    # Every registration was stale: attach no card, so a later jload takes
    # the carries-none path.
    return(list(data = data, dropped = dropped))
  }
  attr(data, ".jst_registrations") <- list(
    registry = reg,
    dummy    = dummy,
    origin   = data_name
  )
  list(data = data, dropped = dropped)
}

#' Internal helper: the calls that make a data frame's registrations again
#'
#' For jload()'s note when a reload clears the registrations set this
#' session (Session 391; the (Session 114) item): the numeric, count and
#' Likert registrations as one jnumeric(), jcount() or jlikert() line each,
#' naming their variables, and the dummy registrations as jdummy() lines --
#' those whose reference the default rule chose in one line, each named
#' reference in a line of its own with ref = (the data's code for a
#' labelled or numeric variable, the category itself, in quotes, for text
#' or a factor; a registration restored from an older file, which does not
#' record how its reference was chosen, names it too). Only variables the
#' loaded data holds are named, so each line runs; a name R reads only in
#' backticks gets them.
#'
#' @param obj_name Character(1). The data frame's name.
#' @param reg The intent registry (.jst_get_registry()), or NULL.
#' @param dummy The dummy registrations (.jst_get_dummy()), or NULL.
#' @param cols Character. The loaded data's variable names.
#' @return Character, the lines without their indent; empty when none.
#' @keywords internal
.jst_registration_lines <- function(obj_name, reg, dummy, cols) {
  bq <- function(v) if (identical(make.names(v), v)) v else paste0("`", v, "`")
  out <- character(0)
  if (length(reg) > 0L) {
    kinds <- vapply(reg, function(r) as.character(r$kind)[1L], character(1))
    for (k in c("numeric", "count", "likert")) {
      vs <- intersect(names(reg)[kinds == k], cols)
      if (length(vs) == 0L) next
      out <- c(out, paste0("j", k, "(", obj_name, ", ",
                           paste(vapply(vs, bq, character(1)), collapse = ", "),
                           ")"))
    }
  }
  if (length(dummy) > 0L) {
    keep <- Filter(function(r) !is.null(r$var_name) && r$var_name %in% cols,
                   dummy)
    auto <- vapply(keep, function(r) isTRUE(r$ref_default), logical(1))
    if (any(auto)) {
      vs <- vapply(keep[auto], function(r) bq(r$var_name), character(1))
      out <- c(out, paste0("jdummy(", obj_name, ", ",
                           paste(vs, collapse = ", "), ")"))
    }
    for (r in keep[!auto]) {
      ref <- if (is.character(r$values) && length(r$values) >= r$ref_idx) {
        paste0("\"", .jst_dq_escape(r$values[r$ref_idx]), "\"")
      } else {
        format(r$ref_code)
      }
      out <- c(out, paste0("jdummy(", obj_name, ", ", bq(r$var_name),
                           ", ref = ", ref, ")"))
    }
  }
  out
}

#' Internal helper: refresh the registration notebook from a loaded frame
#'
#' On load, makes the session notebook for a frame name match what the file
#' carries (the file is the source of truth at load time). When the loaded
#' object carries baked registrations, they are written into the .jst_registry
#' and .jst_dummy notebooks under the load-time name, replacing any differing
#' in-session registrations already sitting under that name. When the loaded
#' object carries none -- a non-.rds file, an older .rds saved before this
#' feature existed, or freshly unregistered data -- any stale registrations
#' under the reused name are cleared. Load-side intersect (S208): before
#' filing, baked entries for variables absent from the loaded frame are
#' dropped, with a note, so a card filed by jload never references a variable
#' the frame lacks. Files written by the S208 courier prune drop nothing
#' here; the intersect cleans cards from files saved before the prune
#' existed. Returns one-line notes describing what happened (or NULL when
#' nothing changed), for the caller to emit subject to its own quiet setting.
#'
#' @param obj_name Character string giving the name the frame is loaded as
#'   (jload's name= argument, or the file stem) -- the key the analysis
#'   functions will look the frame up by.
#' @param baked The ".jst_registrations" attribute read from the loaded object
#'   (a list with registry, dummy, and origin entries), or NULL when the object
#'   carried none.
#' @param cols Character vector of the loaded frame's variable names
#'   (names(df)), used for the load-side intersect.
#' @return A character vector of one-line notes (any intersect drop, then the
#'   restored/cleared note), or NULL when no notebook change was made and
#'   nothing was dropped.
#' @keywords internal
.jst_refresh_registrations <- function(obj_name, baked, cols) {
  notes <- character(0)

  # Load-side intersect (S208): file the card only for variables actually in
  # the loaded frame. Steady-state loads of files written by the courier
  # prune drop nothing; entries dropped here come from files saved before
  # the prune existed (or edited outside jstats).
  emptied_by_intersect <- FALSE
  if (!is.null(baked)) {
    dropped <- character(0)
    if (!is.null(baked$registry)) {
      stale <- setdiff(names(baked$registry), cols)
      if (length(stale) > 0) {
        dropped <- c(dropped, stale)
        baked$registry <- baked$registry[setdiff(names(baked$registry), stale)]
        if (length(baked$registry) == 0) baked$registry <- NULL
      }
    }
    if (!is.null(baked$dummy)) {
      stale <- setdiff(names(baked$dummy), cols)
      if (length(stale) > 0) {
        dropped <- c(dropped, stale)
        baked$dummy <- baked$dummy[setdiff(names(baked$dummy), stale)]
        if (length(baked$dummy) == 0) baked$dummy <- NULL
      }
    }
    dropped <- unique(dropped)
    if (length(dropped) > 0) {
      quoted <- paste0("'", dropped, "'", collapse = ", ")
      notes <- c(notes, if (length(dropped) == 1L) {
        paste0(quoted, " is not in the loaded data, so its saved ",
               "registration was dropped.")
      } else {
        paste0("These variables are not in the loaded data, so their saved ",
               "registrations were dropped: ", quoted, ".")
      })
    }
    if (is.null(baked$registry) && is.null(baked$dummy)) {
      baked <- NULL
      emptied_by_intersect <- TRUE
    }
  }

  existing_reg   <- .jst_get_registry(obj_name)
  existing_dummy <- .jst_get_dummy(obj_name)
  had_existing   <- !is.null(existing_reg) || !is.null(existing_dummy)

  if (is.null(baked)) {
    # Loaded data carries no usable registrations: clear any stale notebook
    # entry sitting under this reused name. Silent when nothing to clear.
    if (had_existing) {
      .jst_set_registry(obj_name, NULL)
      .jst_set_dummy(obj_name, NULL)
      paren <- if (emptied_by_intersect) {
        "(none of the file's saved registrations apply)"
      } else {
        "(the loaded data carries none)"
      }
      # Since Session 391 (the (Session 114) item, Jeff's okay of the lean):
      # the note gives the lines that set the registrations again, for the
      # variables the loaded data holds, so "did I just lose my work?" has
      # its answer under it. The clearing itself is unchanged.
      n_reg <- length(existing_reg) + length(existing_dummy)
      again <- .jst_registration_lines(obj_name, existing_reg,
                                       existing_dummy, cols)
      # The registrations a line can set again: those on a variable the
      # loaded data holds. When some are on variables it lacks, the lead
      # says which ones the lines are.
      n_again <- sum(names(existing_reg) %in% cols) +
        sum(vapply(existing_dummy, function(r)
          !is.null(r$var_name) && r$var_name %in% cols, logical(1)))
      lead <- if (n_again == n_reg) {
        paste0("To set ", if (n_reg == 1L) "it" else "them", " again:\n")
      } else if (n_again == 1L) {
        "To set again the one on a variable the loaded data holds:\n"
      } else {
        "To set again the ones on variables the loaded data holds:\n"
      }
      notes <- c(notes, paste0(
        "Cleared the classification ",
        if (n_reg == 1L) "registration" else "registrations",
        " you had set this session for '", obj_name, "' ", paren, ".",
        if (length(again) > 0L) {
          paste0("\n", lead, paste0("  ", again, collapse = "\n"))
        }))
    }
    return(if (length(notes) > 0) notes else NULL)
  }

  # Loaded data carries registrations: make the notebook match the file.
  replaced <- had_existing &&
    (!identical(existing_reg, baked$registry) ||
       !identical(existing_dummy, baked$dummy))
  .jst_set_registry(obj_name, baked$registry)
  .jst_set_dummy(obj_name, baked$dummy)

  origin_note <- if (!is.null(baked$origin) &&
                     !identical(baked$origin, obj_name)) {
    paste0(" (saved under '", baked$origin, "')")
  } else {
    ""
  }
  notes <- c(notes, if (replaced) {
    paste0("Restored the classification registrations saved with this file",
           origin_note, ", replacing different registrations you had set ",
           "this session for '", obj_name, "'.")
  } else {
    paste0("Restored the classification registrations saved with this file",
           origin_note, ".")
  })
  notes
}

#' Internal helper: note that registrations are not kept in a non-rds format
#'
#' Builds the loss-of-fidelity note emitted when a frame that has active
#' classification registrations is saved to a format other than R
#' format (.rds). Parallels the label and missing-value loss notes: the data
#' write succeeds, but the registrations are dropped because only the .rds
#' format carries them. Returns NULL when the frame has no registrations, so
#' the note fires only when there is something to lose.
#'
#' @param ext The (lower-case) target file extension.
#' @param data_name Character string giving the data frame name to look up.
#' @return A character note, or NULL when the frame has no registrations.
#' @keywords internal
.jst_jsave_registration_loss_note <- function(ext, data_name) {
  reg   <- .jst_get_registry(data_name)
  dummy <- .jst_get_dummy(data_name)
  if (is.null(reg) && is.null(dummy)) {
    return(NULL)
  }
  paste0(
    "Note: classification registrations (jnumeric/jcount/jlikert/jdummy) ",
    "are not kept in ", .jst_format_label(ext), " (.", ext, "); they ",
    "persist only in R format (.rds).")
}

#' Internal helper: human-readable label for a registered intent kind
#'
#' @param kind One of "numeric", "count", "likert", "dummy".
#' @param cap Logical; if TRUE, capitalize the first letter.
#' @return A character label.
#' @keywords internal
.jst_intent_label <- function(kind, cap = FALSE) {
  lab <- switch(kind, numeric = "numeric", count = "count",
                dummy = "dummy", likert = "Likert", kind)
  if (isTRUE(cap)) lab <- paste0(toupper(substring(lab, 1, 1)), substring(lab, 2))
  lab
}

#' Internal helper: clear one variable's dummy registration
#'
#' Removes the \code{.jst_dummy} entry for a single variable in a named data
#' frame, used to enforce mutual exclusion when the variable is re-registered
#' as numeric or count. Returns TRUE when an entry was actually removed (so the
#' caller can report the reclassification).
#'
#' @param data_name Character data-frame name.
#' @param var_name Character variable name.
#' @return Logical, invisibly: TRUE if a dummy entry was cleared.
#' @keywords internal
.jst_clear_dummy_var <- function(data_name, var_name) {
  ds <- .jst_get_dummy(data_name)
  if (is.null(ds) || length(ds) == 0) return(invisible(FALSE))
  keep <- !vapply(ds, function(r) identical(r$var_name, var_name), logical(1))
  if (all(keep)) return(invisible(FALSE))
  ds <- ds[keep]
  if (length(ds) == 0) ds <- NULL
  .jst_set_dummy(data_name, ds)
  invisible(TRUE)
}

#' Internal helper: block a dummy-registered variable from being an outcome
#'
#' LHS-scoped guard for the model functions (jlm / jlogistic / jaov / jt, and
#' future jpoisson / jnegbin). A variable the user registered with jdummy()
#' has been declared categorical-with-a-reference; using it as the response
#' is a category error, so this raises a stop() at DV resolution -- before any
#' IV/group handling. Scoped to the outcome only: a registered dummy is a
#' legitimate predictor (jlm / jlogistic) or grouping variable (jaov / jt),
#' so those uses are never touched. The remedy differs by family: jlogistic
#' points to 0/1 recoding (it needs a binary outcome); the others point to
#' clearing the registration (the variable is then read in its native form).
#'
#' @param data_name Character data-frame name (may be NULL for a bare frame).
#' @param dv_name Character name of the outcome (response) variable.
#' @param fn The calling user-facing function name, e.g. "jlm".
#'
#' @return \code{invisible(NULL)} when the outcome is not a registered dummy;
#'   otherwise signals an error and does not return.
#'
#' @keywords internal
.jst_check_dummy_outcome <- function(data_name, dv_name, fn) {
  ds <- .jst_get_dummy(data_name)
  if (is.null(ds) || length(ds) == 0L) return(invisible(NULL))
  is_dummy <- any(vapply(ds, function(r) identical(r$var_name, dv_name),
                         logical(1)))
  if (!is_dummy) return(invisible(NULL))
  dn <- if (is.null(data_name) || !nzchar(data_name)) "data" else data_name
  if (identical(fn, "jlogistic")) {
    .jst_stop(
      "'", dv_name, "' is registered as a dummy, and can't be an outcome ",
      "variable.\n",
      "To use it as the outcome, ensure 0/1 coding, for example:\n",
      "  ", dn, "$", dv_name, "R <- jrecode(", dn, ", ", dv_name,
        ", map = \"<oldval1>=0; <oldval2>=1\")",
      fn = fn
    )
  } else {
    .jst_stop(
      "'", dv_name, "' is registered as a dummy, and can't be an outcome ",
      "variable.\n",
      "Clear the registration to use the variable directly:\n",
      "  jdummy(", dn, ", ", dv_name, ", remove = TRUE)",
      fn = fn
    )
  }
}

#' Internal helper: clear one variable's intent-registry record
#'
#' Removes the \code{.jst_registry} record for a single variable in a named
#' data frame. Used by \code{jdummy()} to enforce mutual exclusion (a variable
#' that becomes a dummy drops any numeric/count registration).
#'
#' @param data_name Character data-frame name.
#' @param var_name Character variable name.
#' @return The kind that was cleared (character), or NULL if none, invisibly.
#' @keywords internal
.jst_clear_intent_var <- function(data_name, var_name) {
  reg <- .jst_get_registry(data_name)
  if (is.null(reg) || is.null(reg[[var_name]])) return(invisible(NULL))
  cleared <- reg[[var_name]]$kind
  reg[[var_name]] <- NULL
  if (length(reg) == 0) reg <- NULL
  .jst_set_registry(data_name, reg)
  invisible(cleared)
}

#' Internal helper: names of data frames carrying registrations of one kind
#'
#' Scans the relevant session store and returns the names of the data frames
#' that currently hold at least one registration of the requested kind:
#' \code{.jst_registry} for "numeric"/"count" (a frame qualifies if it has any
#' record of that kind), \code{.jst_dummy} for "dummy" (a frame qualifies if it
#' has any dummy registration). Used by the clear dispatcher to decide, when no
#' frame is named and no default is set, whether a bare clear is unambiguous.
#'
#' @param kind One of "numeric", "count", "likert", "dummy".
#' @return Character vector of data-frame names (possibly empty).
#' @keywords internal
.jst_frames_with_registrations <- function(kind) {
  if (identical(kind, "dummy")) {
    all_d <- getOption(".jst_dummy", default = list())
    nm <- names(all_d)[vapply(all_d, function(x) !is.null(x) && length(x) > 0,
                              logical(1))]
    return(if (is.null(nm)) character(0) else nm)
  }
  all_r <- getOption(".jst_registry", default = list())
  keep <- vapply(all_r, function(reg) {
    !is.null(reg) && length(reg) > 0 &&
      any(vapply(reg, function(r) identical(r$kind, kind), logical(1)))
  }, logical(1))
  nm <- names(all_r)[keep]
  if (is.null(nm)) character(0) else nm
}

#' Internal helper: clear one frame's registrations of one kind
#'
#' Removes the requested kind's registrations for a single named data frame and
#' returns the variable names that were cleared (empty when there were none).
#' "dummy" clears the frame's \code{.jst_dummy} entry; "numeric"/"count"/
#' "likert" remove only the matching-kind records from the frame's
#' \code{.jst_registry} entry, leaving any records of the other kinds in
#' place.
#'
#' @param kind One of "numeric", "count", "likert", "dummy".
#' @param data_name Character data-frame name.
#' @return Character vector of cleared variable names (possibly empty).
#' @keywords internal
.jst_clear_one_frame <- function(kind, data_name) {
  if (identical(kind, "dummy")) {
    existing <- .jst_get_dummy(data_name)
    if (is.null(existing) || length(existing) == 0) return(character(0))
    cleared <- vapply(existing, function(r) r$var_name, character(1))
    .jst_set_dummy(data_name, NULL)
    return(unname(cleared))
  }
  reg <- .jst_get_registry(data_name)
  if (is.null(reg) || length(reg) == 0) return(character(0))
  is_kind <- vapply(reg, function(r) identical(r$kind, kind), logical(1))
  if (!any(is_kind)) return(character(0))
  cleared <- vapply(reg[is_kind], function(r) r$var_name, character(1))
  reg <- reg[!is_kind]
  if (length(reg) == 0) reg <- NULL
  .jst_set_registry(data_name, reg)
  unname(cleared)
}

#' Internal helper: the registration verb name for a kind
#'
#' @param kind One of "numeric", "count", "likert", "dummy".
#' @return The user-facing function name
#'   ("jnumeric"/"jcount"/"jlikert"/"jdummy").
#' @keywords internal
.jst_clear_verb <- function(kind) {
  switch(kind, numeric = "jnumeric", count = "jcount", dummy = "jdummy",
         paste0("j", kind))
}

#' Internal helper: resolve and perform a registration clear
#'
#' The single decision point for clearing classification registrations, shared
#' by \code{jnumeric()}, \code{jcount()}, and \code{jdummy()} so the three verbs
#' behave identically. Three entry shapes feed it:
#' \itemize{
#'   \item \code{clear.all = TRUE} -- clear this kind on every data frame that
#'         carries it.
#'   \item \code{explicit_frame} set (the \code{verb(data, NULL)} form) -- clear
#'         this kind on that one frame.
#'   \item neither (the \code{verb(NULL)} form) -- clear the \code{juse()}
#'         default frame if one is set; otherwise clear the sole frame carrying
#'         this kind if exactly one does; otherwise stop and ask the user to
#'         name a frame or pass \code{clear.all = TRUE} (never a silent
#'         multi-frame wipe).
#' }
#' Messages are emitted here, not by the callers, so the wording stays uniform.
#'
#' @param kind One of "numeric", "count", "likert", "dummy".
#' @param clear.all Logical; clear every frame carrying this kind.
#' @param explicit_frame Character data-frame name for the \code{verb(data,
#'   NULL)} form, or NULL.
#' @param default_name The \code{juse()} default frame name, or NULL.
#' @return \code{invisible(NULL)}.
#' @keywords internal
.jst_handle_clear <- function(kind, clear.all = FALSE, explicit_frame = NULL,
                              default_name = NULL) {
  klab <- .jst_intent_label(kind)
  Klab <- .jst_intent_label(kind, cap = TRUE)

  report_one <- function(frame, cleared, default = FALSE) {
    tag <- if (isTRUE(default)) " (the default data frame)" else ""
    if (length(cleared) == 0) {
      .jst_msg("No ", klab, " registrations to clear for ", frame, tag, ".")
    } else {
      .jst_msg(Klab, " registrations cleared for ", frame, tag, ": ",
               paste(cleared, collapse = ", "), ".")
    }
  }

  # clear.all: every frame carrying this kind.
  if (isTRUE(clear.all)) {
    frames <- .jst_frames_with_registrations(kind)
    if (length(frames) == 0) {
      .jst_msg("No ", klab, " registrations to clear.")
      return(invisible(NULL))
    }
    for (fr in frames) .jst_clear_one_frame(kind, fr)
    .jst_msg(Klab, " registrations cleared across all data frames (",
             paste(frames, collapse = ", "), ").")
    return(invisible(NULL))
  }

  # verb(data, NULL): clear the named frame only.
  if (!is.null(explicit_frame)) {
    report_one(explicit_frame, .jst_clear_one_frame(kind, explicit_frame))
    return(invisible(NULL))
  }

  # verb(NULL): default frame wins when one is set.
  if (!is.null(default_name)) {
    report_one(default_name, .jst_clear_one_frame(kind, default_name),
               default = TRUE)
    return(invisible(NULL))
  }

  # verb(NULL), no default: clear the sole registered frame, else nothing,
  # else ask rather than wipe several silently.
  frames <- .jst_frames_with_registrations(kind)
  if (length(frames) == 0) {
    .jst_msg("No ", klab, " registrations to clear.")
    return(invisible(NULL))
  }
  if (length(frames) == 1) {
    report_one(frames, .jst_clear_one_frame(kind, frames))
    return(invisible(NULL))
  }
  verb <- .jst_clear_verb(kind)
  .jst_stop(Klab, " registrations exist on more than one data frame: ",
       paste(frames, collapse = ", "), ".\n",
       "Name the one to clear, for example:\n",
       "  ", verb, "(", frames[1], ", NULL)\n",
       "Or clear them all:\n",
       "  ", verb, "(clear.all = TRUE)")
}

#' Internal helper: shared registration engine for jnumeric() / jcount() /
#' jlikert()
#'
#' Validates the requested variables, then either removes their registrations
#' of the given kind (\code{remove = TRUE}) or writes them, enforcing mutual
#' exclusion: writing a record replaces any prior intent record for that
#' variable (one record per variable in \code{.jst_registry}) and clears any
#' \code{.jst_dummy} registration for it. Any reclassification (a variable that
#' previously carried a different intent or a dummy registration) is reported.
#' A standard-tier reminder notes that registrations are session-only and how
#' to persist them.
#'
#' @param kind One of "numeric", "count", "likert".
#' @param data The resolved data frame.
#' @param data_name Character data-frame name (the registry key).
#' @param default_used Logical; whether the \code{juse()} default frame was used.
#' @param var_names Character vector of variable names to register.
#' @param remove Logical; if TRUE, remove rather than write.
#' @param file_stem Character(1); the file name in the durability note's
#'   two lines (\code{.jst_data_file_stem()}). The data frame's name by
#'   default.
#' @return \code{invisible(NULL)}.
#' @keywords internal
.jst_register_intent <- function(kind, data, data_name, default_used,
                                 var_names, remove, file_stem = data_name) {
  .jst_check_vars(data, var_names, data_name)

  if (isTRUE(remove)) {
    return(.jst_remove_registrations(kind, data_name, var_names))
  }

  # Every variable is checked before any is registered (Session 342), so a
  # call that is refused has changed nothing.
  for (v in var_names) .jst_check_registration_type(kind, data[[v]], v)

  reg <- .jst_get_registry(data_name)
  if (is.null(reg)) reg <- list()
  reclass <- character(0)
  for (v in var_names) {
    prior <- reg[[v]]
    if (!is.null(prior) && !identical(prior$kind, kind)) {
      reclass <- c(reclass, paste0("'", v, "' (", .jst_intent_label(prior$kind),
                                   " -> ", .jst_intent_label(kind), ")"))
    }
    if (isTRUE(.jst_clear_dummy_var(data_name, v))) {
      reclass <- c(reclass, paste0("'", v, "' (dummy -> ",
                                   .jst_intent_label(kind), ")"))
    }
    reg[[v]] <- list(var_name = v, kind = kind)
  }
  .jst_set_registry(data_name, reg)

  if (isTRUE(default_used)) .jst_default_note(data_name)
  .jst_msg(.jst_intent_label(kind, cap = TRUE), " registration set for ",
           paste0("'", var_names, "'", collapse = ", "), " in ", data_name, ".")
  if (length(reclass) > 0) {
    .jst_msg("  Reclassified: ", paste(reclass, collapse = "; "), ".")
  }
  if (!identical(getOption(".jst_output_level", "standard"), "minimal")) {
    .jst_msg(.jst_durability_note("session", data_name,
                                  count = length(var_names),
                                  file_stem = file_stem))
  }

  # Non-blocking declaration-plausibility heads-up for the just-registered
  # variables (count/likert; numeric is a no-op). (Session 91)
  .jst_declaration_note(data, var_names, kind)

  invisible(NULL)
}

#' Internal helper: can a variable carry a numeric, count or Likert registration?
#'
#' TRUE for a numeric variable and for a haven-labelled variable whose
#' stored values are numbers -- the two storage kinds \code{jnumeric()},
#' \code{jcount()} and \code{jlikert()} document. Read from
#' \code{.jst_var_kind()}, so a factor, a text variable (plain or
#' value-labelled), a logical, a date or time and the unsupported types are
#' all FALSE. One test for the three places that need it: the registration
#' refusal (\code{.jst_check_registration_type()}) and the two readers of a
#' stored registration (\code{.jst_jstats_class()}, \code{.jst_is_count()}),
#' which pass over one that is stored on any other kind of variable.
#'
#' @param x A variable.
#' @return \code{TRUE} or \code{FALSE}.
#' @keywords internal
.jst_takes_numeric_registration <- function(x) {
  .jst_var_kind(x)$kind %in% c("numeric", "labelled")
}

#' Internal helper: refuse a registration the variable's type cannot carry
#'
#' \code{jnumeric()}, \code{jcount()} and \code{jlikert()} assert an analysis
#' role for a variable that holds numbers. Until Session 342 they accepted
#' any variable and confirmed the registration as if it had changed
#' something: \code{jnumeric(d, Sev)} on a factor printed "Numeric
#' registration set" while \code{jdesc()} went on refusing Sev, and
#' \code{jscreen()} showed a text variable as "Numeric / User-declared"
#' over R's "NAs introduced by coercion" (the S310 item). The Classification
#' reference's registration scope boundary (Session 79) had always said the
#' storage-determined kinds are refused with guidance to convert first;
#' Jeff's Session 342 lean 2 extended the refusal to every kind but numeric
#' and haven-labelled numeric, a logical included. The wording follows
#' \code{jrelabel(labels = )} and \code{jdeclare_missing()}, which refuse
#' the same kinds: a factor or text variable is pointed to
#' \code{jencode()}; the other kinds have no conversion jstats performs,
#' and get the fact alone. \code{jdummy()} is not gated here -- it registers
#' a categorical role, which every one of these kinds but the dates and the
#' unsupported types can take.
#'
#' @param kind \code{"numeric"}, \code{"count"} or \code{"likert"}.
#' @param x The variable.
#' @param var_name Its name.
#' @return Invisibly \code{NULL}; stops when the variable is refused.
#' @keywords internal
.jst_check_registration_type <- function(kind, x, var_name) {
  if (.jst_takes_numeric_registration(x)) return(invisible(NULL))
  article <- if (identical(kind, "numeric")) "a numeric" else
    paste0("a ", .jst_intent_label(kind))
  only <- paste0("; ", article,
                 " registration applies only to numeric variables.")
  fn   <- .jst_clear_verb(kind)
  if (inherits(x, c("Date", "POSIXct", "POSIXlt", "difftime"))) {
    .jst_stop("'", var_name, "' is a date/time variable", only, fn = fn)
  }
  if (is.factor(x)) {
    .jst_stop("'", var_name, "' is a factor", only, "\n",
              .jst_txt_jencode_first, fn = fn)
  }
  if (is.character(x)) {
    .jst_stop("'", var_name, "' is a character (text) variable", only, "\n",
              .jst_txt_jencode_first, fn = fn)
  }
  if (is.logical(x)) {
    .jst_stop("'", var_name, "' is a logical (TRUE/FALSE) variable", only,
              fn = fn)
  }
  .jst_stop("'", var_name, "' is of type ", typeof(x),
            " and cannot be registered.", fn = fn)
}

#' Internal helper: remove named variables' registrations of one kind
#'
#' The \code{remove = TRUE} half of the four registration verbs, working
#' from the data frame's NAME alone: the stores are keyed by name, so a
#' registration can be removed after its data frame is gone
#' (\code{.jst_registration_by_name()}; Session 342). "numeric", "count"
#' and "likert" remove a variable's record from the \code{.jst_registry}
#' notebook only when it is of that kind; "dummy" removes its
#' \code{.jst_dummy} entry.
#'
#' @param kind One of "numeric", "count", "likert", "dummy".
#' @param data_name Character; the data frame's name.
#' @param var_names Character; the variables named.
#' @return \code{invisible(NULL)}. Called for its message.
#' @keywords internal
.jst_remove_registrations <- function(kind, data_name, var_names) {
  removed <- character(0)
  if (identical(kind, "dummy")) {
    ds <- .jst_get_dummy(data_name)
    if (!is.null(ds)) {
      drop    <- vapply(ds, function(r) r$var_name %in% var_names, logical(1))
      removed <- vapply(ds[drop], function(r) r$var_name, character(1))
      ds      <- ds[!drop]
      if (length(ds) == 0) ds <- NULL
      .jst_set_dummy(data_name, ds)
    }
  } else {
    reg <- .jst_get_registry(data_name)
    for (v in var_names) {
      rec <- if (!is.null(reg)) reg[[v]] else NULL
      if (!is.null(rec) && identical(rec$kind, kind)) {
        reg[[v]] <- NULL
        removed  <- c(removed, v)
      }
    }
    if (!is.null(reg) && length(reg) == 0) reg <- NULL
    .jst_set_registry(data_name, reg)
  }
  if (length(removed) > 0) {
    .jst_msg(.jst_intent_label(kind, cap = TRUE), " registration removed for ",
             paste0("'", removed, "'", collapse = ", "), " in ", data_name, ".")
  } else {
    .jst_msg("No ", .jst_intent_label(kind), " registration to remove for ",
             paste0("'", var_names, "'", collapse = ", "), " in ", data_name, ".")
  }
  invisible(NULL)
}

#' Internal helper: a registration verb's named clear or removal, by name
#'
#' \code{jdummy(z, NULL)} and \code{jdummy(z, Grp, remove = TRUE)} -- and
#' the \code{jnumeric()}, \code{jcount()} and \code{jlikert()} forms -- name
#' the data frame whose registrations are to go. The stores are keyed by
#' NAME, so neither needs the data frame; until Session 342 the name was
#' resolved as a data frame first, and one that had been removed, or now
#' held something else, stopped at the resolver ("'z' is not a data frame.
#' Did you mean to use it as a variable name?"), leaving the registrations
#' out of the named form's reach (the S334 item; \code{jsubset()} and
#' \code{jcomplete()} got the by-name forms at v0.9.211, and this follows
#' them through \code{.jst_setting_name_state()}).
#'
#' Called before the resolver. Acts, and returns \code{TRUE}, when the
#' first argument is a bare name that does not hold a data frame and
#' registrations of this kind are stored under it. A lone \code{NULL} with
#' nothing stored under the name is refused as a name
#' (\code{.jst_registration_name_stop()}) when no \code{juse()} default is
#' set; with a default, and for the removal form whenever nothing is
#' stored, the call is left to the resolver, since the name may be a
#' variable of the default data frame. REGISTERING under such a name is
#' never served here: it stays the resolver's refusal (Jeff's Session 342
#' lean 3).
#'
#' @param kind One of "numeric", "count", "likert", "dummy".
#' @param data_sub The substituted first argument.
#' @param dots The unevaluated \code{...} of the call, as a list.
#' @param remove The call's \code{remove} flag.
#' @param envir The caller's environment.
#' @return \code{TRUE} when the call was served here, otherwise
#'   \code{FALSE}; stops for a name that carries nothing.
#' @keywords internal
.jst_registration_by_name <- function(kind, data_sub, dots, remove, envir) {
  if (!is.symbol(data_sub) || length(dots) == 0L) return(FALSE)
  if (!is.null(names(dots)) && any(nzchar(names(dots)))) return(FALSE)
  lone_null <- length(dots) == 1L && is.null(dots[[1L]])
  if (!lone_null && !isTRUE(remove)) return(FALSE)
  st <- .jst_setting_name_state(
    data_sub, .jst_frames_with_registrations(kind),
    getOption(".jst_default_data", default = NULL), envir)
  if (is.null(st)) return(FALSE)
  if (lone_null) {
    if (!st$stored) .jst_registration_name_stop(kind, st)
    .jst_handle_clear(kind, explicit_frame = st$name)
    return(TRUE)
  }
  if (!st$stored) return(FALSE)
  var_names <- vapply(dots, function(e) paste(deparse(e), collapse = ""),
                      character(1))
  .jst_remove_registrations(kind, st$name, var_names)
  TRUE
}

#' Internal helper: the stop for a named clear whose name carries nothing
#'
#' \code{jdummy(z, NULL)} where \code{z} is not a data frame and no dummy
#' registration is stored under that name (Session 342). The registration
#' verbs' form of \code{.jst_setting_name_stop()}'s first message: the name
#' is the subject (voice Rule AD) and takes no article and no "data frame",
#' since it is not one; "was not found" for a name that did not evaluate
#' and "is not a data frame" for one that holds something else (Rule AH);
#' the status call is the remedy.
#'
#' @param kind One of "numeric", "count", "likert", "dummy".
#' @param st The \code{.jst_setting_name_state()} result.
#' @return Does not return; stops.
#' @keywords internal
.jst_registration_name_stop <- function(kind, st) {
  fn <- .jst_clear_verb(kind)
  .jst_stop(
    st$name,
    if (identical(st$state, "gone")) " was not found" else
      " is not a data frame",
    ", and no ", .jst_intent_label(kind),
    " registrations are stored under that name.\n",
    "To see the registrations that are stored, run:\n",
    "  ", fn, "()",
    fn = fn)
}

#' Internal helper: resolve which data frame a bare \code{f(NULL)} clears
#'
#' The single decision point for the bare-\code{NULL} form of the two
#' toggleable pipeline setters, \code{jsubset(NULL)} and
#' \code{jcomplete(NULL)}, so the pair resolves a frame exactly as the
#' registration verbs' \code{.jst_handle_clear()} does (S289 alignment,
#' shipped S294): the \code{juse()} default frame when one is set;
#' otherwise the sole frame carrying a setting when exactly one does;
#' otherwise -- more than one frame and no default -- stop and ask the
#' user to name a frame or pass \code{clear.all = TRUE}, never a silent
#' multi-frame wipe. The caller performs the clear and emits its own
#' message; this helper only chooses the frame, or stops.
#'
#' @param fn_label Character function label (\code{"jsubset"} or
#'   \code{"jcomplete"}), used in the ambiguity error.
#' @param frames Character vector of the data frame names currently
#'   carrying a setting of this kind (NULL entries already dropped).
#' @param default_name The \code{juse()} default frame name, or \code{NULL}.
#'
#' @return The name of the frame to clear, or \code{NULL} when no frame
#'   carries a setting and no default is set (the caller reports "nothing
#'   to clear"). Never returns when the choice is ambiguous.
#'
#' @keywords internal
.jst_pipeline_clear_target <- function(fn_label, frames, default_name = NULL) {
  if (!is.null(default_name)) return(default_name)
  if (length(frames) == 0L) return(NULL)
  if (length(frames) == 1L) return(frames)
  .jst_stop("more than one data frame carries a ", fn_label, " setting: ",
            paste(frames, collapse = ", "), ".\n",
            "Name the one to clear, for example:\n",
            "  ", fn_label, "(", frames[1L], ", NULL)\n",
            "Or clear them all:\n",
            "  ", fn_label, "(clear.all = TRUE)")
}

#' Internal helper: render a pipeline-state clear message
#'
#' Shared formatter for the clear messages of \code{jsubset()} and
#' \code{jcomplete()} (\code{jdummy()} used it too until the registration
#' verbs unified on \code{.jst_handle_clear()}, which renders its own).
#' Owns the collapse layout so the two setters stay byte-identical: one
#' data frame renders on a single line; two or more render a header line
#' plus one indented \code{"  - "} line per data frame.
#'
#' @param fn_label Character function label used in the message prefix
#'   (e.g. \code{"jsubset"}).
#' @param dnames Character vector of data frame names being cleared.
#' @param payloads Character vector, parallel to \code{dnames}, giving the
#'   parenthesised "what was lost" text for each frame (e.g.
#'   \code{"had: Age < 40"} or \code{"had 2 registered: Religion, Region"}).
#'
#' @return \code{invisible(NULL)}. Called for its message side effect.
#'
#' @keywords internal
.jst_render_clear <- function(fn_label, dnames, payloads) {
  n <- length(dnames)
  if (n == 1L) {
    .jst_msg(fn_label, " cleared for ", dnames[1L], " (", payloads[1L], ").")
  } else {
    lines <- paste0("  - ", dnames, " (", payloads, ")")
    .jst_msg(fn_label, " cleared (", .jst_fmt_n(n), " data frames):\n",
             paste(lines, collapse = "\n"))
  }
  invisible(NULL)
}

#' Internal helper: render a pipeline-state session-wide status overview
#'
#' Shared formatter for the two-or-more-frame status overview of
#' \code{jsubset()} and \code{jcomplete()} (the toggleable setters). Renders
#' a header line plus one indented \code{"  - "} line per data frame, each
#' tagged \code{[active]} / \code{[inactive]} and marked \code{, default}
#' for the current \code{juse()} default. The zero- and one-frame cases stay
#' with the callers, since their single-line wording differs (and
#' \code{jcomplete} appends a live complete-case count there). \code{jdummy}
#' does not use this helper: it has no active/inactive toggle and its
#' overview header reads "registrations" rather than "settings".
#'
#' @param fn_label Character function label (e.g. \code{"jsubset"}).
#' @param dnames Character vector of data frame names.
#' @param payloads Character vector, parallel to \code{dnames}, giving the
#'   per-frame payload shown after the colon (the expression for
#'   \code{jsubset}; the comma-joined variable list for \code{jcomplete}).
#' @param active Logical vector, parallel to \code{dnames}, TRUE when the
#'   setting is active.
#' @param default_name Character name of the current \code{juse()} default,
#'   or \code{NULL}. The matching frame is tagged \code{, default}.
#' @param unusable Logical vector parallel to \code{dnames}, or NULL. TRUE
#'   tags the frame \code{, cannot be applied}: its stored setting would
#'   stop an analysis as things stand (Session 331).
#'
#' @return \code{invisible(NULL)}. Called for its message side effect.
#'
#' @keywords internal
.jst_render_status_overview <- function(fn_label, dnames, payloads, active,
                                        default_name = NULL,
                                        unusable = NULL) {
  tags   <- ifelse(active, "active", "inactive")
  is_def <- if (is.null(default_name)) rep(FALSE, length(dnames)) else
              dnames == default_name
  tags   <- ifelse(is_def, paste0(tags, ", default"), tags)
  if (!is.null(unusable)) {
    tags <- ifelse(unusable, paste0(tags, ", cannot be applied"), tags)
  }
  lines  <- paste0("  - ", dnames, ": ", payloads, "  [", tags, "]")
  .jst_msg(fn_label, " settings (", .jst_fmt_n(length(dnames)), " data frames):\n",
           paste(lines, collapse = "\n"))
  invisible(NULL)
}

#' Internal helper: build canonical dummy variable naming for a categorical variable
#'
#' Single source of truth for how categorical variables are turned into named
#' dummy columns across the package. Called by \code{jdummy()} during
#' registration and by \code{jlm()} / \code{jlogistic()} when handling
#' \code{categorical =} arguments and auto-detected categorical IVs.
#'
#' Supports six input shapes:
#' \enumerate{
#'   \item haven_labelled with descriptive labels not containing the
#'         variable name (e.g. Gender labelled "Male", "Female").
#'   \item haven_labelled with descriptive labels already containing the
#'         variable name (e.g. Program labelled "Program 1", "Program 2"...).
#'   \item haven_labelled with labels that equal the codes as strings
#'         (i.e. uninformative -- labels carry no extra information).
#'   \item Plain numeric with no labels.
#'   \item Factor with character levels.
#'   \item Character vector.
#' }
#'
#' Naming algorithm:
#' \enumerate{
#'   \item Output form is always \code{VarName_Suffix}.
#'   \item Suffix source per category: descriptive label if available,
#'         numeric code otherwise. Mixed within a single variable is allowed
#'         (descriptive wins per-category).
#'   \item Canonicalise the chosen suffix: replace runs of non-alphanumeric
#'         characters with single underscore; trim leading and trailing
#'         underscores; if a suffix canonicalises to empty (label was entirely
#'         non-alphanumeric), fall back to that category's code.
#'   \item Anti-stutter: if the canonicalised suffix already begins with
#'         \code{paste0(var_name, "_")}, do not prepend the variable name
#'         again.
#'   \item Detect duplicates: if two categories produce the same final name,
#'         stop with an error pointing to \code{jrelabel()}.
#' }
#'
#' Permissive reference matching: when \code{ref} is a character string,
#' three matching attempts are made -- direct match against canonical labels,
#' canonicalised user input matched against canonical labels (so
#' \code{"Program 3"} or \code{"3"} both find \code{"Program_3"}), and
#' string match against codes (so \code{"3"} also matches code 3).
#'
#' @param x A vector -- haven_labelled, factor, character, or numeric.
#' @param var_name Character. The variable's name (used as the dummy
#'   column prefix).
#' @param ref Reference category specifier. May be \code{auto} (the
#'   default: for a two-category variable the reference is chosen so the
#'   affirmative or code-1 category is modeled -- see the \code{ref}
#'   documentation in \code{jdummy()}; otherwise the first category),
#'   \code{first}, \code{last}, a numeric code, or a character string
#'   matching a canonical label.
#' @param max.categories Integer. Maximum number of input categories allowed;
#'   a variable with more raises an error rather than building the dummy set.
#'   Default \code{20L}.
#' @param data_name Character. Name of the source data frame, used only to
#'   build the suggested-fix call shown in the over-the-limit error. May be
#'   \code{NULL}.
#'
#' @return A list with components: \code{codes}, \code{labels}
#'   (canonical, used for display), \code{dummy_names} (canonical, for
#'   non-reference categories only), \code{var_type}, \code{values} (the
#'   raw category value behind each code, in code order: the factor
#'   levels or the sorted character values, otherwise the codes
#'   themselves -- what \code{.jst_expand_one_dummy()} matches cases
#'   against for factor and character variables; Session 305),
#'   \code{ref_idx}, \code{ref_code}, \code{ref_label},
#'   \code{non_ref_idx}, \code{notes} (character vector of informational
#'   messages), \code{warnings_msg} (character vector of warnings; empty
#'   since Session 347, when the one warning it carried was retired: see
#'   Step 7).
#'
#' @keywords internal
.jst_make_dummy_names <- function(x, var_name, ref = "auto",
                                  max.categories = 20L,
                                  data_name = NULL) {

  notes        <- character(0)
  warnings_msg <- character(0)

  # -- Step 1: classify input and extract codes + raw labels ----------------
  is_haven <- haven::is.labelled(x)

  if (is_haven && is.character(x)) {
    # A string variable carrying value labels (a .sav stores Sex "M" / "F"
    # this way). Its values are text, so it registers as a character
    # variable does -- codes are positions, the raw strings travel as
    # `values` -- with one difference: a value's label, where it has one,
    # names its dummy. Until S340 this fell into the numeric-labelled arm
    # below, every code coerced to NA, and the stop was "Cannot create
    # unique dummy names ... 'NA' and 'NA' both produce 'NA'". A declared
    # missing string is excluded with the NA cells: is.na() is TRUE for it
    # on a live haven_labelled_spss column.
    var_type   <- "character"
    val_labels <- labelled::val_labels(x)
    x_chr      <- as.character(unclass(.jst_label_blanks(x)))
    uniq       <- sort(unique(x_chr[!is.na(x)]))
    # A blank cell is a category (see the plain-text arm below): last.
    uniq       <- c(uniq[uniq != .jst_blank_label],
                    uniq[uniq == .jst_blank_label])
    codes      <- seq_along(uniq)
    values     <- uniq
    raw_labels <- uniq
    if (!is.null(val_labels) && length(val_labels) > 0L) {
      lab_vals <- as.character(unname(val_labels))
      hit      <- match(uniq, lab_vals)
      has_lab  <- !is.na(hit) & nzchar(names(val_labels)[hit])
      raw_labels[has_lab] <- names(val_labels)[hit[has_lab]]
    }
  } else if (is_haven) {
    var_type   <- "haven_labelled"
    val_labels <- labelled::val_labels(x)
    codes      <- .jst_as_numeric(sort(unique(x[!is.na(x)])))
    values     <- codes
    raw_labels <- character(length(codes))
    for (i in seq_along(codes)) {
      match_idx <- which(val_labels == codes[i])
      if (length(match_idx) > 0) {
        raw_labels[i] <- names(val_labels)[match_idx[1]]
      } else {
        raw_labels[i] <- as.character(codes[i])
      }
    }
  } else if (is.factor(x)) {
    # Factor and character codes are POSITION indices, so the raw values
    # travel with the registration as `values` (Session 305, AUDIT-037):
    # the expansion matches cases against them, never against the column
    # coerced to numeric.
    var_type   <- "factor"
    lvls       <- levels(droplevels(x))
    codes      <- seq_along(lvls)
    values     <- lvls
    raw_labels <- lvls
  } else if (is.character(x)) {
    var_type   <- "character"
    # A blank cell is a category, as it is a group in jt(), jaov() and
    # jcrosstab() (Jeff's Session 340 ruling, "A"): the empty and the
    # whitespace cells together, under the one label, placed LAST so that
    # the first category -- the default reference of a variable with three
    # or more -- is a named one. Until then an empty cell was left out of
    # the category set and dropped from the model as missing, uncounted in
    # the Missing data block, while a whitespace cell was a category of
    # its own (and, sorting first, the reference).
    x          <- .jst_label_blanks(x)
    uniq       <- sort(unique(x[!is.na(x)]))
    uniq       <- c(uniq[uniq != .jst_blank_label],
                    uniq[uniq == .jst_blank_label])
    codes      <- seq_along(uniq)
    values     <- uniq
    raw_labels <- uniq
  } else if (is.logical(x)) {
    # Logical (TRUE/FALSE) predictors (AUDIT-004): treat as a two-category
    # variable so a saved comparison (over40 <- Age > 40) models like any
    # other dichotomy. Codes are the OBSERVED 0/1 values, so a constant
    # logical still hits the fewer-than-2-categories stop below; with both
    # values present the reference resolves to FALSE, so the dummy
    # reads as the effect of being TRUE (Var_TRUE), matching how base R's
    # lm()/glm() name a logical predictor's coefficient.
    var_type   <- "logical"
    codes      <- sort(unique(as.numeric(x[!is.na(x)])))
    values     <- codes
    raw_labels <- ifelse(codes == 1, "TRUE", "FALSE")
  } else if (is.numeric(x)) {
    var_type   <- "numeric"
    codes      <- sort(unique(x[!is.na(x)]))
    values     <- codes
    raw_labels <- as.character(codes)
  } else {
    .jst_stop("'", var_name, "' has an unsupported type for dummy coding ",
         "(class: ", paste(class(x), collapse = "/"), ").")
  }

  n_cats <- length(codes)
  if (n_cats < 2) {
    .jst_stop("'", var_name, "' has fewer than 2 categories.\n",
         "Cannot create dummy variables.")
  }
  # Values that are not whole numbers (Session 375; the jdummy() guardrails
  # item, its thresholds calibrated): a variable measured to a fraction --
  # SelfControl = 3.7 -- is a scale, not a set of categories, and dummy
  # coding it gave one indicator per distinct value. It stops, ahead of the
  # category limit below, whose way out (raise the limit) does not fit it.
  # The item's two warnings (10 to 20 categories; a range that looks
  # continuous) were not built: the limit of 20 already stops a continuous
  # variable's many values (Session 127), and a variable of 12 categories
  # named in jdummy() is the user's stated intent (Jeff's okay, Session 375).
  if (var_type %in% c("numeric", "haven_labelled")) {
    frac <- codes[abs(codes - round(codes)) > sqrt(.Machine$double.eps)]
    if (length(frac) > 0L) {
      shown <- format(frac[seq_len(min(3L, length(frac)))], trim = TRUE,
                      digits = 7L)
      .jst_stop(var_name, " has values that are not whole numbers (",
                paste(shown, collapse = ", "),
                if (length(frac) > 3L) ", ...", "), so it ",
                "cannot be dummy-coded.\n",
                "Dummy coding makes one indicator for each category.\nIf ",
                "these values are categories, recode them to whole-number ",
                "codes first with jrecode().")
    }
  }
  if (n_cats > max.categories) {
    raise_to   <- (n_cats %/% 10L + 1L) * 10L
    dn         <- if (is.null(data_name) || !nzchar(data_name)) "data" else data_name
    raise_line <- paste0("  jdummy(", dn, ", ", var_name,
                         ", max.categories = ", raise_to, ")")
    via_dummy  <- identical(tryCatch(.jst_caller_fn(), error = function(e) NULL),
                            "jdummy")
    if (via_dummy) {
      .jst_stop(
        "'", var_name, "' has ", .jst_fmt_n(n_cats), " categories, the default limit is ",
        max.categories, ".\n",
        "You can raise the limit with:\n",
        raise_line
      )
    } else {
      .jst_stop(
        "'", var_name, "' has ", .jst_fmt_n(n_cats), " categories, more than the ",
        max.categories, "-category limit for dummy coding.\n",
        "To dummy-code this many, register it with jdummy and raise the limit:\n",
        raise_line
      )
    }
  }

  # -- Step 2: choose suffix source per category ----------------------------
  # Per-category rule: use the raw label if it is descriptive (non-empty
  # and not equal to the code-as-string); otherwise use the code.
  #
  # "Descriptive" detection is per-category, so a variable with mixed
  # descriptive and uninformative labels gets the most informative suffix
  # available for each category.

  code_as_str    <- as.character(codes)
  is_descriptive <- nzchar(raw_labels) & raw_labels != code_as_str

  # For non-haven types (factor, character, numeric), is_descriptive is
  # also true when the label genuinely differs from the synthetic code.
  # For numeric (no labels) all are "non-descriptive" → use codes. For
  # factor and character all should be descriptive (raw_labels are the
  # real values, and the codes are synthetic seq_along indices).

  used_code_fallback <- !is_descriptive
  suffix_source      <- ifelse(is_descriptive, raw_labels, code_as_str)

  # -- Step 3: canonicalise each suffix -------------------------------------
  # Letters and digits of any script are kept (Session 390): the rule kept
  # A to Z and 0 to 9 only, so a Chinese or Korean label was wiped -- the
  # dummy named by its code, under a note that the labels "were not
  # available" -- and an accented one cut apart (Sor with its slash, S_r).
  canon <- .jst_dummy_canon(suffix_source)

  # If canonicalisation produced an empty string (label was entirely
  # non-alphanumeric), fall back to the code for that category.
  empty_canon <- !nzchar(canon)
  if (any(empty_canon)) {
    canon[empty_canon]              <- code_as_str[empty_canon]
    used_code_fallback[empty_canon] <- TRUE
  }

  # -- Step 4: anti-stutter and prepend var_name ----------------------------
  prefix          <- paste0(var_name, "_")
  already_prefixed <- startsWith(canon, prefix)
  final_labels    <- ifelse(already_prefixed, canon, paste0(prefix, canon))

  # -- Step 5: duplicate detection ------------------------------------------
  if (anyDuplicated(final_labels) > 0) {
    dup_idx   <- which(duplicated(final_labels) | duplicated(final_labels,
                                                             fromLast = TRUE))
    dup_pairs <- vapply(unique(final_labels[dup_idx]), function(d) {
      offenders <- raw_labels[final_labels == d]
      paste0("'", paste(offenders, collapse = "' and '"),
             "' both produce '", d, "'")
    }, character(1))
    .jst_stop(
      "Cannot create unique dummy names for '", var_name, "': ",
      paste(dup_pairs, collapse = "; "), ".\n",
      "Use jrelabel() to give these categories distinct labels, or ",
      "jrecode() to merge or rename them."
    )
  }

  # -- Step 6: resolve reference category -----------------------------------
  # ref = "auto" (the default): a variable with 3+ categories takes the
  # first (lowest) category as reference, as before. A TWO-category
  # variable is parameterized so the category meaning "presence" is the
  # one modeled: (a) if the two raw labels are a recognized binary pair
  # (.jst_match_binary_tokens -- yes/no, y/n, true/false, t/f,
  # present/absent, success/failure; case-insensitive), the AFFIRMATIVE is
  # modeled and the negative is the reference, the same rule jlogistic
  # applies to its outcome encoding; (b) otherwise, for numeric-coded
  # inputs where one code equals 1, that category is modeled (a 1 = Yes /
  # 2 = No variable models Yes; a 0/1 variable models 1, as before);
  # (c) otherwise the first category is the reference, as before.
  # Factor/character/logical inputs get artificial position codes, so tier
  # (b) is restricted to genuinely numeric codings; an explicit
  # ref = "first" keeps its literal code-order meaning.
  if (is.character(ref) && tolower(ref) == "auto") {
    ref_idx <- 1L
    if (n_cats == 2L) {
      m <- .jst_match_binary_tokens(raw_labels)
      if (isTRUE(m$recognized)) {
        ref_idx <- which(raw_labels == m$reference)[1L]
      } else if (var_type %in% c("haven_labelled", "numeric") &&
                 any(codes == 1)) {
        ref_idx <- which(codes != 1)[1L]
      } else if (identical(var_type, "character") &&
                 any(values == .jst_blank_label)) {
        # (b2) a text variable coded as one word or blank ("Y" or nothing):
        # the word is the presence, so it is modeled and the blank category
        # is the reference -- tier (a)'s rule for a yes/no pair (S340).
        ref_idx <- which(values == .jst_blank_label)[1L]
      }
    }
  } else if (is.character(ref) && tolower(ref) == "first") {
    ref_idx <- 1L
  } else if (is.character(ref) && tolower(ref) == "last") {
    ref_idx <- n_cats
  } else if (is.numeric(ref)) {
    ref_idx <- which(codes == ref)
    if (length(ref_idx) == 0) {
      .jst_stop("Reference code ", ref, " not found in '", var_name,
           "'.\nAvailable codes: ", paste(codes, collapse = ", "))
    }
  } else if (is.character(ref)) {
    # Try direct match against canonical labels first.
    ref_idx <- which(final_labels == ref)
    if (length(ref_idx) == 0) {
      # Try canonicalising the user's input the same way labels were
      # canonicalised, then match.
      cleaned_ref <- .jst_dummy_canon(ref)
      if (nzchar(cleaned_ref) && !startsWith(cleaned_ref, prefix)) {
        cleaned_ref <- paste0(prefix, cleaned_ref)
      }
      ref_idx <- which(final_labels == cleaned_ref)
    }
    if (length(ref_idx) == 0) {
      # Last try: match against codes-as-strings (so ref = "3" works for
      # code 3 even when canonical label is "Program_3").
      ref_idx <- which(code_as_str == ref)
    }
    if (length(ref_idx) == 0) {
      # A label matched without regard to case (Session 356): the pointer
      # for a category typed bare prints it as typed, and the line must
      # run; a match is taken only when it is one category.
      cands <- which(tolower(raw_labels) == tolower(ref) |
                     tolower(final_labels) == tolower(ref))
      if (length(cands) == 1L) ref_idx <- cands
    }
    if (length(ref_idx) == 0) {
      .jst_stop("Reference '", ref, "' not found in '", var_name,
           "'.\nAvailable labels: ", paste(final_labels, collapse = ", "))
    }
  } else {
    ref_idx <- 1L
  }

  ref_idx     <- as.integer(ref_idx[1])
  ref_code    <- codes[ref_idx]
  ref_label   <- final_labels[ref_idx]
  non_ref_idx <- setdiff(seq_len(n_cats), ref_idx)
  dummy_names <- final_labels[non_ref_idx]

  # -- Step 7: build informational notes ------------------------------------
  # The note prints through .jst_msg_out(), one sentence a line, wrapped by
  # width (Session 347): it was printed by cat() as one line of some 300
  # characters, at five sites.
  if (any(used_code_fallback)) {
    notes <- c(notes, paste0(
      "(Note: One or more dummy names for '", var_name, "' were built ",
      "from numeric codes because descriptive value labels were not ",
      "available.\nIf these names aren't ideal, use jrelabel() to set ",
      "value labels, or jrecode() to change the underlying values, ",
      "then re-register with jdummy().)"
    ))
  }

  # No warning for a long dummy name (retired Session 347). It said that
  # names over 30 characters would make "coefficient tables ... look
  # awkward" and asked for shorter labels; since the grouped coefficient
  # rows (Session 320) the tables show each category by its value label
  # under its variable, and a long name is seen only in the VIF table,
  # whole. It also fired on a long VARIABLE name whose labels were short,
  # and listed the reference, which has no dummy.

  list(
    codes        = codes,
    labels       = final_labels,
    dummy_names  = dummy_names,
    var_type     = var_type,
    values       = values,
    ref_idx      = ref_idx,
    ref_code     = ref_code,
    ref_label    = ref_label,
    non_ref_idx  = non_ref_idx,
    notes        = notes,
    warnings_msg = warnings_msg
  )
}


#' Internal helper: a category label made into the end of a dummy's name
#'
#' Session 390 (the non-English probe): every run of characters that are
#' not letters, combining marks or digits becomes one underscore, and the
#' underscores at either end are dropped -- letters of ANY script, so a
#' Chinese, Japanese or Korean label and an accented one keep their
#' letters. The rule kept A to Z and 0 to 9 only, so such a label lost
#' every letter and the dummy was named by its code, under a note that
#' its value labels were not available. One rule for
#' \code{.jst_make_dummy_names()}, its \code{ref =} matching and
#' \code{.jst_dummy_category_values()}.
#' @param x Character vector.
#' @param ascii TRUE gives the A-to-Z rule, which names stored before
#'   Session 390 were made by.
#' @return Character vector, the same length.
#' @keywords internal
.jst_dummy_canon <- function(x, ascii = FALSE) {
  out <- if (ascii) gsub("[^A-Za-z0-9]+", "_", x)
         else gsub("[^\\p{L}\\p{M}\\p{N}]+", "_", x, perl = TRUE)
  gsub("^_+|_+$", "", out)
}

#' Internal helper: the category values behind a dummy registration
#'
#' Returns the raw category value each registration code stands for, in
#' code order. Registrations built since Session 305 carry them as the
#' \code{values} field, which is returned as stored. A registration
#' saved by an earlier version (a jdummy() card in an older .rds file)
#' has no such field, so the values are reconstructed. For a factor or
#' character variable the codes are POSITION indices 1..k, and the
#' reconstruction cannot simply re-sort the column: a category absent
#' from the frame in hand -- filtered out, or not in this file -- would
#' shift every later position onto the wrong code. Instead each candidate
#' value in the column is canonicalized exactly as
#' \code{.jst_make_dummy_names()} builds a dummy name and matched against
#' the registration's stored labels, which pins each value to the code it
#' was registered under. A registered category with no matching value in
#' the column is left NA, so its dummy comes out all zero, as an absent
#' numeric code does. For numeric, haven-labelled and logical variables
#' the codes are the values themselves.
#'
#' @param reg A registration object (\code{var_name}, \code{var_type},
#'   \code{codes}, \code{labels}, optionally \code{values}).
#' @param col The variable's column, used only for the reconstruction.
#' @return A vector the length of \code{reg$codes}: character for factor
#'   and character registrations, numeric otherwise.
#' @keywords internal
.jst_dummy_category_values <- function(reg, col) {
  if (!is.null(reg$values)) return(reg$values)
  if (!identical(reg$var_type, "factor") &&
      !identical(reg$var_type, "character")) {
    return(reg$codes)
  }
  cand <- if (is.factor(col)) {
    levels(droplevels(col))
  } else {
    col_chr <- as.character(col)
    sort(unique(col_chr[!is.na(col_chr) & nzchar(col_chr)]))
  }
  # The same canonicalization and anti-stutter steps as
  # .jst_make_dummy_names(); a value whose canonical form is empty fell
  # back to its code there, which cannot be recovered here and stays NA.
  # A registration stored before Session 390 holds names made by the
  # A-to-Z rule, so a value not found by today's form is looked for by
  # that one.
  prefix <- paste0(reg$var_name, "_")
  named  <- function(canon) {
    ifelse(nzchar(canon),
           ifelse(startsWith(canon, prefix), canon, paste0(prefix, canon)),
           NA_character_)
  }
  hit    <- match(named(.jst_dummy_canon(cand)), reg$labels)
  old    <- is.na(hit)
  hit[old] <- match(named(.jst_dummy_canon(cand[old], ascii = TRUE)),
                    reg$labels)
  values <- rep(NA_character_, length(reg$codes))
  values[hit[!is.na(hit)]] <- cand[!is.na(hit)]
  values
}


#' Internal helper: expand a single registration into dummy columns
#'
#' Given a registration-shaped object (from jdummy storage or built
#' in-flight via \code{.jst_make_dummy_names()}), add the dummy columns
#' to \code{data} and substitute the variable's symbol in the parsed
#' \code{formula} with the parenthesized dummy block
#' \code{(d1 + d2 + ...)}. Substitution walks the formula object and
#' compares symbols by identity (the resolver's sub_term pattern), so a
#' backticked computed-column name can never be partially matched the way
#' the retired deparse-and-gsub rewrite could (AUDIT-028/-029).
#' Used by \code{.jst_expand_dummies()} and by the auto-categorical
#' pathways in jlm and jlogistic.
#'
#' @param data The data frame.
#' @param formula The model formula (a formula object).
#' @param reg A registration object (must have \code{var_name},
#'   \code{var_type}, \code{codes}, \code{non_ref_idx},
#'   \code{dummy_names}; \code{values} when built since Session 305).
#' @return A list with components \code{data}, \code{formula},
#'   \code{dummy_coef_names}.
#' @keywords internal
.jst_expand_one_dummy <- function(data, formula, reg) {

  col <- data[[reg$var_name]]
  # Factor and character variables are matched in POSITION space (Session
  # 305, AUDIT-037): their registration codes are position indices 1..k,
  # not values, so each case is matched against the registration's
  # category values rather than against the column coerced to numeric --
  # which made every text value NA (the logged crash, every case
  # listwise-deleted) and let a factor's unused level shift the later
  # positions onto the wrong codes (all-zero dummies). Numeric,
  # haven-labelled and logical columns keep the value comparison,
  # unchanged. An NA cell is missing on every dummy; a blank text cell is
  # a category of its own since Session 340 (see below for a registration
  # older than that); a non-missing value the registration does not know
  # is zero on every dummy, as an unregistered numeric code is.
  pos_space <- identical(reg$var_type, "factor") ||
               identical(reg$var_type, "character")
  if (pos_space) {
    col_chr <- as.character(if (is.character(col)) .jst_label_blanks(col)
                            else col)
    is_miss <- is.na(col_chr)
    cat_vals <- .jst_dummy_category_values(reg, col)
    # A blank text cell is a category since Session 340, and a registration
    # made since then lists it. One made BEFORE (a card restored from an
    # older .rds file) does not, and for it a blank cell stays what it was
    # when the registration was made: missing on every dummy.
    if (is.character(col) && !(.jst_blank_label %in% cat_vals)) {
      is_miss <- is_miss | (col_chr == .jst_blank_label & !is.na(col_chr))
    }
    pos     <- match(col_chr, cat_vals)
  } else {
    orig_col <- .jst_as_numeric(col)
  }
  dummy_coef_names <- character(0)

  # Collision guard (AUDIT-013): if a generated dummy name already matches an
  # existing column, the write below would silently overwrite it and fit the
  # wrong model. Checked before any write, so names(data) still reflects only
  # pre-existing columns (working copy only; the user's data frame is
  # untouched either way).
  collision <- reg$dummy_names[reg$dummy_names %in% names(data)]
  if (length(collision) > 0) {
    .jst_stop(
      "Expanding '", reg$var_name, "' would create the dummy column '",
      collision[1], "', but a column with that name already exists.\n",
      "Rename the category with jrelabel() so the dummy gets a different name."
    )
  }

  for (j in seq_along(reg$non_ref_idx)) {
    idx   <- reg$non_ref_idx[j]
    dname <- reg$dummy_names[j]
    data[[dname]] <- if (pos_space) {
      ifelse(is_miss, NA_integer_, as.integer(!is.na(pos) & pos == idx))
    } else {
      ifelse(is.na(orig_col), NA_integer_,
             as.integer(orig_col == reg$codes[idx]))
    }
    dummy_coef_names <- c(dummy_coef_names, dname)
  }

  # Substitute the variable's symbol with the dummy block, by identity, on
  # the parsed formula (AUDIT-029; the resolver's sub_term walker is the
  # pattern). The parentheses keep interaction terms correct
  # (y ~ x * Religion -> y ~ x * (Rel_B + Rel_C)). The dummy names are
  # assembled with call()/as.name() rather than parsed from text, so a
  # non-syntactic dummy name cannot produce a parse failure. In-place
  # editing preserves the formula's class and environment.
  target <- as.name(reg$var_name)
  repl   <- call("(", Reduce(function(a, b) call("+", a, b),
                             lapply(reg$dummy_names, as.name)))
  sub_sym <- function(e) {
    if (is.name(e)) {
      if (identical(e, target)) return(repl)
      return(e)
    }
    if (is.call(e)) {
      for (k in seq_along(e)) {
        if (k == 1L) next
        if (identical(as.list(e)[[k]], substitute())) next
        e[[k]] <- sub_sym(e[[k]])
      }
    }
    e
  }
  for (k in 2:length(formula)) formula[[k]] <- sub_sym(formula[[k]])

  list(data = data, formula = formula,
       dummy_coef_names = dummy_coef_names)
}


#' Internal helper: expand registered dummy variables in a formula and data frame
#'
#' Checks for jdummy registrations matching variables in the formula,
#' creates temporary dummy columns in the data frame, rewrites the formula,
#' and returns updated data, formula, reference category labels, and dummy
#' coefficient names. Used by jlm and jlogistic.
#'
#' A per-call numeric = or count = naming a registered dummy IV overrides the
#' registration for that one call (Option B): the variable is skipped before
#' expansion -- left intact as its original numeric column rather than expanded
#' then reverted -- and a message (registered dichotomy) or warning (registered
#' multi-category dummy) is emitted. The stored registration is never mutated.
#'
#' @param data The data frame.
#' @param formula The model formula.
#' @param data_name Character string name of the data frame (for looking up registrations).
#' @param numeric Optional character vector of variable names given a per-call
#'   numeric = override by the calling analysis function. A registered dummy
#'   named here is skipped from expansion (Option B) and left as its original
#'   numeric column; the stored registration is not changed.
#' @param count Optional character vector of variable names given a per-call
#'   count = override. Treated identically to \code{numeric} for expansion
#'   purposes (a count predictor enters a model as a numeric column).
#'
#' @return A list with components:
#'   \describe{
#'     \item{data}{The data frame with dummy columns added.}
#'     \item{formula}{The updated formula with dummy names.}
#'     \item{ref_cats}{Character vector of "VarName = RefLabel" strings.}
#'     \item{expanded_originals}{Character vector of the original variable
#'       names actually expanded into dummy columns (registered, minus any
#'       skipped by a per-call numeric=/count= override, minus any not in the
#'       formula). Callers use this to identify which originals were replaced.}
#'     \item{dummy_coef_names}{Character vector of dummy column names (for blanking beta).}
#'   }
#'
#' @keywords internal
.jst_expand_dummies <- function(data, formula, data_name,
                                numeric = NULL, count = NULL) {

  model_vars         <- all.vars(formula)
  dummy_regs         <- .jst_get_dummy(data_name)
  ref_cats           <- character(0)
  dummy_coef_names   <- character(0)
  expanded_originals <- character(0)

  if (!is.null(dummy_regs) && length(dummy_regs) > 0) {
    dv_name     <- model_vars[1]

    for (reg in dummy_regs) {
      if (reg$var_name %in% model_vars && reg$var_name != dv_name) {

        # Option B (skip-before-expand): a per-call numeric =/ count = naming
        # a registered dummy IV wins over the registration for this one call.
        # Consult the override BEFORE expanding -- leave the original column
        # intact (no expand-then-revert) and skip it, so the variable flows on
        # to the analysis function's numeric/count branch as a plain numeric
        # predictor. The stored registration is never mutated (per-call only).
        if (reg$var_name %in% c(numeric, count)) {
          arg_label <- if (reg$var_name %in% numeric) "numeric" else "count"
          # Subclass split uses the SAME dichotomy test .jst_class_from_role()
          # uses for the registry Sub-class label, so the override message and
          # jscreen always agree on a given variable.
          if (.jst_is_dichotomy(data[[reg$var_name]])$is_dichotomy) {
            # Registered dichotomy -> mild consequential note (always shown).
            .jst_msg(
              arg_label, " = takes precedence for ", reg$var_name,
              " (registered as a dummy via jdummy); entering it as numeric ",
              "for this model.\nThe registration is unchanged."
            )
          } else {
            # Registered multi-category dummy -> real warning: collapsing its
            # category codes into one slope is an interval-scale assumption.
            .jst_warn(
              arg_label, " = takes precedence for ", reg$var_name,
              " (registered as a dummy via jdummy); entering it as numeric ",
              "for this model, so its category codes enter as a single ",
              "numeric predictor -- treating them as an interval scale.\n",
              "The registration is unchanged."
            )
          }
          next
        }

        expanded <- .jst_expand_one_dummy(data, formula, reg)
        data               <- expanded$data
        formula            <- expanded$formula
        dummy_coef_names   <- c(dummy_coef_names, expanded$dummy_coef_names)
        expanded_originals <- c(expanded_originals, reg$var_name)

        ref_cats <- c(ref_cats, paste0(reg$var_name, " = ", reg$ref_label))
      }
    }
  }

  list(data = data, formula = formula, ref_cats = ref_cats,
       dummy_coef_names = dummy_coef_names,
       expanded_originals = expanded_originals)
}


#' Internal helper: remove dummy columns from an expanded formula
#'
#' Drops named dummy symbols from the \code{+} chains
#' \code{.jst_expand_one_dummy()} wrote, walking the parsed formula the
#' same way that helper substituted them (by identity, never by text),
#' so an interaction term keeps its shape: \code{x * (g_b + g_c + g_d)}
#' with \code{g_b} dropped becomes \code{x * (g_c + g_d)}. Used by
#' \code{.jst_prune_absent_categories()} (Session 306), which drops the
#' dummies of categories that have no case in the analysis sample; that
#' caller guarantees at least one dummy of every block survives, so a
#' block never empties.
#'
#' @param formula The expanded model formula.
#' @param drop Character vector of dummy column names to remove.
#' @return The formula with those symbols removed.
#' @keywords internal
.jst_drop_formula_terms <- function(formula, drop) {
  drop_syms  <- lapply(drop, as.name)
  is_dropped <- function(e) {
    any(vapply(drop_syms, function(s) identical(s, e), logical(1)))
  }
  walk <- function(e) {
    if (is.name(e)) return(if (is_dropped(e)) NULL else e)
    if (!is.call(e)) return(e)
    if (identical(e[[1L]], as.name("+")) && length(e) == 3L) {
      a <- walk(e[[2L]])
      b <- walk(e[[3L]])
      if (is.null(a)) return(b)
      if (is.null(b)) return(a)
      return(call("+", a, b))
    }
    if (identical(e[[1L]], as.name("(")) && length(e) == 2L) {
      inner <- walk(e[[2L]])
      if (is.null(inner)) return(NULL)
      return(call("(", inner))
    }
    for (k in seq_along(e)) {
      if (k == 1L) next
      if (identical(as.list(e)[[k]], substitute())) next
      r <- walk(e[[k]])
      if (is.null(r)) {
        stop("internal: a dropped dummy stood alone in the formula",
             call. = FALSE)
      }
      e[[k]] <- r
    }
    e
  }
  for (k in 2:length(formula)) {
    r <- walk(formula[[k]])
    if (is.null(r)) {
      stop("internal: a dropped dummy stood alone in the formula",
           call. = FALSE)
    }
    formula[[k]] <- r
  }
  formula
}
