  Q = 722, R = 667, S = 556, T = 611, U = 722, V = 722, W = 944, X = 722,
  Y = 722, Z = 611,
  "0" = 500, "1" = 500, "2" = 500, "3" = 500, "4" = 500, "5" = 500,
  "6" = 500, "7" = 500, "8" = 500, "9" = 500,
