# makes in the session's own encoding (Session 390).
.jst_docx_char_widths <- c(
  .jst_docx_char_widths,
  stats::setNames(c(564, 500, 500, 500, 500, 500, 500, 500, 1000),
                  c("\u2212", "\u2020", "\u2021", "\u00a7",
                    "\u03b2", "\u03b7", "\u03b1", "\u03c7", "\u2014")))

